  for(String map:new String[]{AbelTownGeometry.ID}){GameView v=town(map);RuntimeState s=state(v);WorldRuntimeAdapter w=TownInteriorTest.field(v,"poteFieldAdapter");capture(v,map+"-entry");assertTrue(w.canPlayerOccupy(s.player().x,s.player().y));for(RuntimeState.Npc npc:s.npcs()){assertTrue(Math.hypot(npc.x-s.player().x,npc.y-s.player().y)>48);assertTrue(CampaignNavigationTest.walk(w,w.requestNpcApproach(npc.id)));}}
