 @Test public void physicalPhoneCanvasUsesLogicalViewportAndKeepsWarmFloorChunks()throws Exception{
  GameView v=town(AbelTownGeometry.ID);WorldRuntimeAdapter w=TownInteriorTest.field(v,"poteFieldAdapter");w.resizeViewport(1170,540);AbelTownRenderer renderer=new AbelTownRenderer(c);renderer.prepare();Bitmap b=Bitmap.createBitmap(2340,1080,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.scale(2,2);renderer.draw(canvas,w,Collections.emptyList());assertEquals(.25f,w.tileStepSeconds(),.001f);long cold=renderer.floorBuildCount();long[] samples=new long[60];for(int i=0;i<samples.length;i++){long t=System.nanoTime();renderer.draw(canvas,w,Collections.emptyList());samples[i]=System.nanoTime()-t;}assertEquals("no per-frame rebuilding caused by physical canvas dimensions",cold,renderer.floorBuildCount());assertTrue(cold<=32);assertTrue(renderer.floorCachePixelBytes()<=8652800);Arrays.sort(samples);JSONObject receipt=new JSONObject().put("physicalCanvas",new JSONArray(new int[]{2340,1080})).put("logicalViewport",new JSONArray(new int[]{1170,540})).put("coldBuilds",cold).put("warmRebuilds",renderer.floorBuildCount()-cold).put("warmP95Ms",samples[56]/1000000d).put("warmMaxMs",samples[59]/1000000d).put("scope","Robolectric native CPU; not handset FPS");java.nio.file.Path file=Paths.get("build/reports/abel-v149/performance.json");Files.createDirectories(file.getParent());Files.write(file,receipt.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));v.layout(0,0,2340,1080);v.draw(new Canvas(b));save(b,"phone-scale-town");assertEquals(.1f,GameView.frameDeltaSeconds(.1f,true),.0001f);assertEquals(.05f,GameView.frameDeltaSeconds(.1f,false),.0001f);
 }
